12	// saveDiffReport builds, saves and returns a report for diff tests.
13	func saveDiffReport(t *testing.T, dir string, artifact Artifact, rules []Rule, invariants map[string]bool) Report {
14		t.Helper()
15		report, err := BuildReport(artifact, rules, invariants, nil)
16		if err != nil {
17			t.Fatal(err)
18		}
19		if err := SaveReport(dir, report); err != nil {
20			t.Fatal(err)
21		}
22		return report
23	}
24	
25	// storeFileNames lists the files currently in the store directory.
26	func storeFileNames(t *testing.T, dir string) []string {
27		t.Helper()
28		entries, err := os.ReadDir(dir)
29		if err != nil {
30			t.Fatal(err)
31		}
32		names := make([]string, 0, len(entries))
33		for _, e := range entries {
34			names = append(names, e.Name())
35		}
36		sort.Strings(names)
37		return names
38	}
