166	func TestDiffAbsentSideIsNull(t *testing.T) {
167		dir := t.TempDir()
168		artifact := sampleArtifact()
169		before := saveDiffReport(t, dir, artifact, nil, nil)
170		after := saveDiffReport(t, dir, artifact,
171			[]Rule{{ID: "r1", Kind: "static", Severity: "low", Invariant: "inv", Version: "1"}},
172			map[string]bool{"inv": false})
173	
174		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
175		if err != nil {
176			t.Fatal(err)
177		}
178		if len(diff.Results) != 1 || diff.Results[0].Change != ChangeRuleAdded {
179			t.Fatalf("results = %+v", diff.Results)
180		}
181		if diff.Results[0].Before != nil {
182			t.Error("absent before side must be null")
183		}
184		if diff.Results[0].After == nil || diff.Results[0].After.Finding == nil {
185			t.Error("added defect rule must carry its evidence")
186		}
187	}
