300			t.Errorf("no-change = %d, want %d", diff.Summary.NoChange, len(sampleRules()))
301		}
302		if diff.Summary.NewDefects != 0 || diff.Summary.ResolvedDefects != 0 || diff.Summary.StatusChanges != 0 {
303			t.Errorf("summary = %+v", diff.Summary)
