334	func TestDiffDeterministicByteIdentical(t *testing.T) {
335		dir := t.TempDir()
336		artifact := sampleArtifact()
337		rules := sampleRules()
338		before := saveDiffReport(t, dir, artifact, rules, sampleInvariants())
339		// Same logical report, different rule storage order.
340		reversed := []Rule{rules[2], rules[1], rules[0]}
341		after := saveDiffReport(t, dir, artifact, reversed, sampleInvariants())
342		if before.ReportID != after.ReportID {
343			t.Fatal("rule order must not change the report id")
344		}
345	
346		first, err := DiffStore(dir, before.ReportID, after.ReportID)
347		if err != nil {
348			t.Fatal(err)
349		}
350		second, err := DiffStore(dir, before.ReportID, after.ReportID)
351		if err != nil {
352			t.Fatal(err)
353		}
354		b1, _ := json.MarshalIndent(first, "", "  ")
355		b2, _ := json.MarshalIndent(second, "", "  ")
356		if string(b1) != string(b2) {
357			t.Fatal("repeated diffs must be byte-identical")
358		}
359		if strings.Contains(string(b1), "time") || strings.Contains(string(b1), "date") {
