1	package main
2	
3	import (
4		"path/filepath"
5		"strings"
6		"testing"
7	
8		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
9	)
10	
11	// 本文件在真实命令行进程边界上回归保护“规则变化”与“已消除缺陷”的区分：
12	// 同一规则标识在基准报告为“发现缺陷”、新报告为“通过”时，只有两侧完整规则
13	// 定义一致才是“已消除缺陷”；只改一项定义（这里刻意保持版本字符串不变、只
14	// 改严重级别）必须是“规则变化”。两侧报告都通过真实 audit 命令正常归档，再
15	// 由 diff 命令读回比较，既有报告格式、报告标识与基准/新比较方向保持兼容。
16	
17	// cliRuleChangeRule 构造一条需要 ABI 的规则；两份报告都审计同一带 ABI 的
18	// 产物（mixedCheckArtifact），因此需要 ABI 的规则可以正常保存和读回。
19	func cliRuleChangeRule(severity string) cliWireRule {
20		return cliWireRule{
21			ID:          "reentrancy-guard",
22			Kind:        "static",
23			Severity:    severity,
24			Invariant:   "no-reentrant-withdraw",
25			RequiresABI: true,
26			Version:     "10.2.0", // 漂移用例中版本字符串刻意保持不变
27		}
28	}
29	
30	// TestCLIDiffDefinitionDriftWithSameVersionIsRuleChange 在进程边界上覆盖：
31	// 版本字符串未变、严重级别已经改变时，发现缺陷 -> 通过只能记为“规则变化”。
32	func TestCLIDiffDefinitionDriftWithSameVersionIsRuleChange(t *testing.T) {
33		bin := auditBinary(t)
34		work := t.TempDir()
35		store := filepath.Join(work, "reports")
36		artifact := mixedCheckArtifact()
37		hash := mixedArtifactHash(t)
38	
39		beforeRule := cliRuleChangeRule("high")
40		afterRule := cliRuleChangeRule("critical") // 只改严重级别，其余定义相同
41		before := auditDiffReport(t, bin, work, store, "before.json", artifact,
42			[]cliWireRule{beforeRule},
43			[]cliWireCheck{{ArtifactHash: hash, RuleID: beforeRule.ID, Version: beforeRule.Version,
44				Status: contractsentinel.StatusDefect, Note: resolvedEvidence}})
45		after := auditDiffReport(t, bin, work, store, "after.json", artifact,
46			[]cliWireRule{afterRule},
47			[]cliWireCheck{{ArtifactHash: hash, RuleID: afterRule.ID, Version: afterRule.Version,
48				Status: contractsentinel.StatusPass}})
49	
50		stdout, stderr, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
51		if code != 0 {
52			t.Fatalf("diff must succeed, exit=%d stderr=%s", code, stderr)
53		}
54		d := decodeDiff(t, stdout)
55	
56		// 报告标识与比较方向按命令行参数保留，两侧产物为同一带 ABI 的产物。
57		if d.Before.ReportID != before.ReportID || d.After.ReportID != after.ReportID {
58			t.Errorf("refs = %q/%q, want %q/%q", d.Before.ReportID, d.After.ReportID, before.ReportID, after.ReportID)
59		}
60		if d.ArtifactNameChanged || d.ArtifactHashChanged {
61			t.Error("same artifact must not be flagged changed")
62		}
63	
64		if len(d.Results) != 1 {
65			t.Fatalf("results = %d, want 1", len(d.Results))
66		}
67		entry := d.Results[0]
68		if entry.Change != contractsentinel.ChangeRuleChanged {
69			t.Fatalf("change = %q, want %q", entry.Change, contractsentinel.ChangeRuleChanged)
70		}
71	
72		// 计数：规则变化为一；已消除缺陷、新发现缺陷、检查状态变化均为零。
73		s := d.Summary
74		if s.ChangedRules != 1 {
75			t.Errorf("changedRules = %d, want 1", s.ChangedRules)
76		}
77		if s.ResolvedDefects != 0 || s.NewDefects != 0 || s.StatusChanges != 0 {
78			t.Errorf("defect/status transitions must be zero when the definition changed: %+v", s)
79		}
80		// 两个缺陷总数反映各自报告的实际发现，不能被当作已消除缺陷数量。
