		t.Errorf("after side must keep the trailing space verbatim: %+v", entry.After)
	}
	// 字节层面：带尾随空格的新证据逐字出现在输出里（JSON 转义后空格仍在）。
	escaped := strings.ReplaceAll(base+" ", "\n", `\n`)
